CustomField.formula:
IF(ISBLANK(PeriodTo__c), "",
    /* 1. 날짜 + 서수(st, nd, rd, th) 조합 */
    TEXT(DAY(DATEVALUE(PeriodTo__c))) &
    IF(OR(DAY(DATEVALUE(PeriodTo__c)) = 11, DAY(DATEVALUE(PeriodTo__c)) = 12, DAY(DATEVALUE(PeriodTo__c)) = 13), "th",
        CASE(MOD(DAY(DATEVALUE(PeriodTo__c)), 10),
            1, "st",
            2, "nd",
            3, "rd",
            "th"
        )
    ) & " " &

    /* 2. 영문 월 이름 */
    CASE(MONTH(DATEVALUE(PeriodTo__c)),
        1, "January", 2, "February", 3, "March", 4, "April", 5, "May", 6, "June",
        7, "July", 8, "August", 9, "September", 10, "October", 11, "November", 12, "December", 
        "" /* None 대신 빈 값 */
    ) & " " &

    /* 3. 연도 */
    TEXT(YEAR(DATEVALUE(PeriodTo__c))) & " (" &

    /* 4. 시간 (HH:mm) - GMT 0 */
    MID(TEXT(PeriodTo__c), 12, 5) & ")"
)
